import csv
import io
import json

def reject_constant(value):
    raise ValueError(f"Invalid JSON number: {value}")

def process(data):
    try:
        value = json.loads(data["selection"], parse_constant=reject_constant)
    except json.JSONDecodeError as error:
        raise ValueError(
            f"Invalid JSON: {error.msg} "
            f"(line {error.lineno}, column {error.colno})"
        ) from error

    if isinstance(value, dict):
        rows = [value]
    elif isinstance(value, list) and all(isinstance(row, dict) for row in value):
        rows = value
    else:
        raise ValueError(
            "Expected a JSON object or array of objects"
        )
    if not rows:
        raise ValueError("JSON array is empty")

    headers = []
    for row in rows:
        for header in row:
            if header not in headers:
                headers.append(header)
    if not headers:
        raise ValueError("JSON objects have no fields")

    def cell(value, row, header):
        if isinstance(value, (dict, list)):
            raise ValueError(
                f"Nested JSON values are not supported: row {row}, field {header}"
            )
        if value is None:
            return ""
        if isinstance(value, bool):
            return "true" if value else "false"
        return str(value)

    buffer = io.StringIO(newline="")
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(headers)
    for index, row in enumerate(rows, start=1):
        writer.writerow([cell(row.get(header), index, header) for header in headers])

    result = buffer.getvalue()
    return result[:-1] if result.endswith("\n") else result
